// TH14 v1.00b Stage 1 wave 3, entry st01.ecl.txt:813-822 MainSub02.
// Independent invincible-wave shell. Source frame 0 = first GirlC01 creation (st01:815);
// card shell waits OPENING_BUFFER before that point.
// Source type -> TH14_* mapping per transcribe/th14/bullet-types.md (0-23 same slot).

const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

const TH14_BALL2: int = 432;      // source type 5
const TH14_RING_BALL: int = 448;  // source type 6
const TH14_RICE: int = 480;       // source type 8

// Source EX type 2 (ANIM, a=1) on every emitter below: birth position -= 4*velocity.
// The birth animation itself is omitted per the shared policy; the displacement is kept.
sub fire_one(shape: int, color: int, speed: fx, a: angle) {
    var back: fx = -4fx * speed;
    var x: fx = $self_x + back * cos(a);
    var y: fx = $self_y + back * sin(a);
    _ = fire(shape, color, x, y, speed, a, none, none);
}

// etAim mode 0/1 fan: F(N,i) = 0,-d,+d,-2d,+2d... (aim-modes.md).
sub fire_fan(shape: int, color: int, n: int, spread: angle, speed: fx, aim: angle) {
    var step: int = spread as int;
    for i in 0..n {
        var off: int = 0;
        if n % 2 == 0 {
            off = (i / 2) * step + step / 2;
        } else {
            off = ((i + 1) / 2) * step;
        }
        if i % 2 != 0 { off = -off; }
        fire_one(shape, color, speed, ((aim as int) + off) as angle);
    }
}

// etAim mode 0, count=1, multiple speed layers on one aim angle.
sub fire_layers_aim(shape: int, color: int, m: int, s0: fx, s1: fx, aim: angle) {
    for q in 0..m {
        var v: fx = s0;
        if m > 1 { v = s0 + (s1 - s0) * q / (m - 1); }
        fire_one(shape, color, v, aim);
    }
}

// etAim mode 3 fixed-direction ring: angle = base + 2pi*i/n + q*delta.
// Source creation order is layer outer, path inner.
sub fire_ring(shape: int, color: int, n: int, m: int, base: angle, delta: angle, s0: fx, s1: fx) {
    var db: int = delta as int;
    for q in 0..m {
        var v: fx = s0;
        if m > 1 { v = s0 + (s1 - s0) * q / (m - 1); }
        for i in 0..n {
            var ab: int = (base as int) + (i * 65536) / n + q * db;
            fire_one(shape, color, v, ab as angle);
        }
    }
}

// Source 424 mirror: at the writing point flip movement angle theta -> pi - theta.
sub mv(dur: int, a: angle, speed: fx, easing: int, mirror: int) {
    var aa: angle = a;
    if mirror != 0 { aa = 180deg - a; }
    move_vel(dur, aa, speed, easing);
}

// st01.ecl.txt:343-366 GirlC01 (called by both GirlC01 instances).
async sub girl_c01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx);                    // st01:351 setHurtbox(32,32) -> r 16
    set_hitbox(12fx);                     // st01:352 setHitbox(24,24) -> r 12
    // st01:353-354 FINAL_X > 0 -> mirror; passed in as the entry snapshot.
    mv(0, 45deg, 3fx, EASE_LINEAR, mirror);          // st01:356 moveVel(0.7853982,3.0)
    mv(80, 0deg, 1fx, EASE_QUAD_IN, mirror);         // st01:357 moveVelTime(80,1,0,1.0)
    spawn girl_c01_at();                             // st01:358 async
    wait(60);                                        // st01:359
    loop { wait(1000); }                             // st01:361-364
}

// st01.ecl.txt:368-423 GirlC01_at
async sub girl_c01_at() {
    var r: int = global(GVAR_RANK);
    var cnt: int = 1;      // st01:375-384 E1 N1 H3 L5
    var bursts: int = 1;   // st01:388 diffI(1,3,6,12)
    var gap: int = 4;      // st01:398-407 E4 N4 H2 L1
    var tail: int = 60;    // st01:410-419 E60 N60 H30 L20
    var base: fx = 1fx;    // st01:391 diffF(1,1,2,3)
    if r == 2 { cnt = 3; bursts = 6; gap = 2; tail = 30; base = 2fx; }
    if r >= 3 { cnt = 5; bursts = 12; gap = 1; tail = 20; base = 3fx; }
    wait(60);                                        // st01:371
    for b in 0..bursts {
        var spd: fx = base;                          // st01:391 reset per burst
        for c in 0..12 {
            // st01:372-387 aimed fan, type8 color6, spread 5deg
            fire_fan(TH14_RICE, 6, cnt, 5deg, spd, aim_player());
            spd = spd + 0.1fx;                       // st01:396 after etSpeed
            wait(gap);
        }
        wait(tail);
    }
}

