    loop { wait(1000); }                             // st01:216-219
}

// st01.ecl.txt:223-251 GirlB01_at
async sub girl_b01_at() {
    var r: int = global(GVAR_RANK);
    var n1: int = 6;   var m1: int = 1;   var s1: fx = 1.2fx;  // st01:238 etCountD/etSpeedD
    var m0: int = 5;   var s0: fx = 1.2fx;                     // st01:230/232
    var waves: int = 1;                                        // st01:243 diffI(1,3,3,3)
    if r >= 1 { waves = 3; }
    if r == 2 { n1 = 24; m1 = 2; s1 = 2.2fx; m0 = 1; s0 = 2.2fx; }
    if r >= 3 { n1 = 32; m1 = 3; s1 = 3.2fx; m0 = 3; s0 = 3.2fx; }
    wait(60);                                        // st01:226
    // st01:239 %RANDRAD, sampled once at emitter-1 configuration.
    var rb: int = rand(65536) - 32768;
    // st01:235-242 etOn(1): fixed ring, type8 color4, spread 3deg as layer rotation.
    fire_ring(TH14_RICE, 4, n1, m1, rb as angle, 3deg, s1, 1fx);
    for w in 0..waves {
        // st01:245-248 etOn(0): aimed, 1 path x m0 speed layers, type6 color6.
        fire_layers_aim(TH14_RING_BALL, 6, m0, s0, 1fx, aim_player());
        wait(40);
    }
}

// st01.ecl.txt:34-80 GirlA01_at
async sub girl_a01_at() {
    var r: int = global(GVAR_RANK);
    var d: int = 0;
    if r < 2 { d = rand(300); } else { d = rand(60); }   // st01:37-46 RAND % 300 / % 60
    var spd: fx = 1.2fx;   // st01:52-61 E1.2 N1.2 H2.4 L4.0
    var waves: int = 1;    // st01:63 diffI(1,1,5,10)
    var gap: int = 30;     // st01:67-76 E30 N30 H60 L60
    if r == 2 { spd = 2.4fx; waves = 5; gap = 60; }
    if r >= 3 { spd = 4fx; waves = 10; gap = 60; }
    wait(d);
    for w in 0..waves {
        // st01:47-62 aimed single, type5 color6
        fire_one(TH14_BALL2, 6, spd, aim_player());
        wait(gap);
    }
}

// st01.ecl.txt:103-125 GirlA01b, entered via GirlBlueA01b/GirlRedA01b (st01:316-323, 577-584).
async sub fairy(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                    // st01:105 setHurtbox(24,24) -> r 12
    set_hitbox(8fx);                      // st01:106 setHitbox(16,16) -> r 8
    mv(0, 67.5deg, 4fx, EASE_LINEAR, mirror);        // st01:107 moveVel(1.1780972,4.0)
    mv(60, 45deg, 2.4fx, EASE_LINEAR, mirror);       // st01:108 moveVelTime(60,0,0.7853982,2.4)
    // st01:109-110 !L setDeath("DeadAttack1"): death callback only; invincible shell has no
    // player DPS, so the death sub is unreachable and not synthesized (task policy).
    wait(60);                                        // st01:112
    if global(GVAR_RANK) >= 1 { spawn girl_a01_at(); }  // st01:113-114 !NHL async
    mv(120, -45deg, 1.2fx, EASE_LINEAR, mirror);     // st01:116
    wait(120);                                       // st01:117
    var off: int = rand(3641) - 1820;                // st01:118 %RANDF2 * 0.08726646 (5deg)
    mv(120, 180deg + (off as angle), 2.5fx, EASE_LINEAR, mirror);
    loop { wait(1000); }                             // st01:120-123
}

