// st01.ecl.txt:813-822 MainSub02 timing chain.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-224fx, 32fx, 600, 0, 0, 0, girl_c01(0));  // st01:815
    wait(120);                                                  // st01:816
    _ = spawn_enemy(224fx, 32fx, 600, 0, 0, 0, girl_c01(1));   // st01:817
